// Captures git/build metadata at build time and writes
// src/__generated__/build-info.ts as an exported BUILD_INFO constant.
// The web bundle reads this so the in-game About panel can display the
// exact branch + commit + version a user is running, without ambiguity.
//
// Runs as the first step of `npm run web:build`, before tsc/vite, so
// the generated file is type-checked and bundled into the single-file
// HTML the WebView loads.

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { releaseInfo } from './release-info.mjs';

const OUTPUT = 'src/__generated__/build-info.ts';

function git(cmd, fallback = '') {
  try {
    return execSync(`git ${cmd}`, { encoding: 'utf8' }).trim();
  } catch {
    return fallback;
  }
}

const branch       = git('rev-parse --abbrev-ref HEAD', 'unknown');
const commit       = git('rev-parse HEAD', 'unknown');
const commitShort  = git('rev-parse --short HEAD', 'unknown');
// Untracked + uncommitted files mean the embedded SHA doesn't fully
// describe the running code; surface this so the About panel can flag it.
const dirty        = git('status --porcelain') !== '';
const builtAt      = new Date().toISOString();

const pkg     = JSON.parse(readFileSync('package.json', 'utf8'));
const app     = JSON.parse(readFileSync('app.json', 'utf8'));
// The shipped app version is app.json's (the runtime version follows it).
const appVersion        = app?.expo?.version ?? pkg.version ?? 'unknown';
const androidVersionCode = app?.expo?.android?.versionCode ?? null;
const appName   = app?.expo?.name ?? 'unknown';
const packageId = app?.expo?.android?.package ?? 'unknown';

// Android SDK levels the native build is generated with: pinned in app.json
// through the expo-build-properties plugin so they are explicit and
// reviewable (CI checks the built APK against them). The installed APK's own
// value is not readable at runtime, so About shows these as build config.
function sdkLevel(name) {
  const plugins = Array.isArray(app?.expo?.plugins) ? app.expo.plugins : [];
  for (const p of plugins) {
    if (Array.isArray(p) && p[0] === 'expo-build-properties') {
      const v = p[1]?.android?.[name];
      if (typeof v === 'number') return v;
    }
  }
  return null;
}
const minSdk = sdkLevel('minSdkVersion');
const compileSdk = sdkLevel('compileSdkVersion');
const targetSdk = sdkLevel('targetSdkVersion');

// Public name + version come only from release.json (see docs/release-naming.md).
const rel = releaseInfo();

const data = {
  productName: rel.productName, publicVersion: rel.publicVersion,
  branch, commit, commitShort, dirty, builtAt, appVersion, androidVersionCode,
  appName, packageId, minSdk, compileSdk, targetSdk,
};

mkdirSync(dirname(OUTPUT), { recursive: true });
writeFileSync(OUTPUT,
  `// AUTO-GENERATED by scripts/write-build-info.mjs. Do not edit by hand.\n` +
  `// Regenerated each build to capture the git + version state at build time.\n` +
  `export interface BuildInfo {\n` +
  `  productName: string;\n` +
  `  publicVersion: number;\n` +
  `  branch: string;\n` +
  `  commit: string;\n` +
  `  commitShort: string;\n` +
  `  dirty: boolean;\n` +
  `  builtAt: string;\n` +
  `  appVersion: string;\n` +
  `  androidVersionCode: number | null;\n` +
  `  appName: string;\n` +
  `  packageId: string;\n` +
  `  minSdk: number | null;\n` +
  `  compileSdk: number | null;\n` +
  `  targetSdk: number | null;\n` +
  `}\n` +
  `export const BUILD_INFO: BuildInfo = ${JSON.stringify(data, null, 2)};\n`
);

console.log(`write-build-info: ${branch}@${commitShort}${dirty ? ' (dirty)' : ''} → ${OUTPUT}`);
